<!doctype html><html lang="id"><head><meta charset="utf-8"><style>
@page{margin:24mm 13mm 18mm}*{box-sizing:border-box}body{font-family:DejaVu Sans,sans-serif;color:#2f241f;font-size:8px}header{border-bottom:2px solid #2f241f;padding-bottom:9px;margin-bottom:13px}h1{font-size:19px;margin:3px 0}h2{font-size:11px;margin:14px 0 5px}.kicker{color:#a43b20;font-weight:bold;text-transform:uppercase;letter-spacing:1px}.meta{color:#6b625c}.summary{width:100%;border-collapse:separate;border-spacing:5px;margin:-5px}.summary td{border:1px solid #2f241f;padding:8px}.summary .yellow{background:#facc15}.label{font-size:7px;font-weight:bold;text-transform:uppercase}.value{font-size:13px;font-weight:bold;margin-top:4px}.data{width:100%;border-collapse:collapse}.data thead{display:table-header-group}.data tr{page-break-inside:avoid}.data th{background:#fff7cf;border:1px solid #b9aa91;padding:4px;text-align:left}.data td{border:1px solid #d7cdbd;padding:4px}.right{text-align:right!important}.footer{position:fixed;bottom:-11mm;left:0;right:0;border-top:1px solid #b9aa91;padding-top:4px;color:#6b625c;font-size:7px}.page:after{content:counter(page)}
</style></head><body><header><p class="kicker"><?= esc($businessName) ?></p><h1>Laporan <?= esc($title) ?></h1><p>Periode <?= esc($report['period']['label']) ?> · <?= esc(ucfirst($report['period']['type'])) ?></p><p class="meta">Dibuat <?= esc($printedAt) ?> oleh <?= esc($printedBy) ?></p></header><div class="footer"><?= esc($businessName) ?> · <?= esc($title) ?><span style="float:right">Halaman <span class="page"></span></span></div>
<?php $data=$report['data']; $money=static fn(float $v):string=>'Rp'.number_format($v,0,',','.'); ?>
<?php if($report['type']==='stock'): ?><table class="summary"><tr><td class="yellow"><div class="label">Nilai posisi akhir</div><div class="value"><?= $money($data['totalValue']) ?></div></td><td><div class="label">Item</div><div class="value"><?= count($data['position']) ?></div></td><td><div class="label">Mutasi periode</div><div class="value"><?= count($data['movements']) ?></div></td></tr></table><h2>Posisi Stok Akhir Periode</h2><table class="data"><thead><tr><th>SKU</th><th>Item</th><th>Satuan</th><th class="right">Kuantitas</th><th class="right">Nilai</th></tr></thead><tbody><?php if($data['position']===[]): ?><tr><td colspan="5">Tidak ada data pada periode ini</td></tr><?php else: ?><?php foreach($data['position'] as $row): ?><tr><td><?= esc($row['sku']) ?></td><td><?= esc($row['name']) ?></td><td><?= esc($row['base_unit']) ?></td><td class="right"><?= number_format((float)$row['quantity'],3,',','.') ?></td><td class="right"><?= $money((float)$row['value']) ?></td></tr><?php endforeach ?><?php endif ?></tbody></table><h2>Mutasi Stok</h2><table class="data"><thead><tr><th>Waktu</th><th>Item</th><th>Jenis</th><th>Sumber</th><th class="right">Jumlah</th><th class="right">Nilai</th></tr></thead><tbody><?php if($data['movements']===[]): ?><tr><td colspan="6">Tidak ada data pada periode ini</td></tr><?php else: ?><?php foreach($data['movements'] as $row): ?><tr><td><?= esc(date('d/m/Y H:i',strtotime($row['posted_at']))) ?></td><td><?= esc($row['name']) ?></td><td><?= esc($row['movement_type']) ?></td><td><?= esc($row['notes']?:$row['source_type']) ?></td><td class="right"><?= number_format((float)$row['quantity'],3,',','.') ?></td><td class="right"><?= $money((float)$row['total_cost']) ?></td></tr><?php endforeach ?><?php endif ?></tbody></table>
<?php elseif($report['type']==='opnames'): ?><table class="summary"><tr><td class="yellow"><div class="label">Sesi disetujui</div><div class="value"><?= count($data['rows']) ?></div></td><td><div class="label">Total nilai selisih absolut</div><div class="value"><?= $money($data['totalVariance']) ?></div></td></tr></table><h2>Opname yang Diposting</h2><table class="data"><thead><tr><th>Nomor</th><th>Cut-off</th><th>Diposting</th><th>Petugas</th><th class="right">Item</th><th class="right">Nilai selisih</th></tr></thead><tbody><?php if($data['rows']===[]): ?><tr><td colspan="6">Tidak ada data pada periode ini</td></tr><?php else: ?><?php foreach($data['rows'] as $row): ?><tr><td><?= esc($row['opname_number']) ?></td><td><?= esc(date('d/m/Y H:i',strtotime($row['cutoff_at']))) ?></td><td><?= esc(date('d/m/Y H:i',strtotime($row['approved_at']))) ?></td><td><?= esc($row['creator_name']) ?></td><td class="right"><?= (int)$row['item_count'] ?></td><td class="right"><?= $money((float)$row['variance_value']) ?></td></tr><?php endforeach ?><?php endif ?></tbody></table>
<?php elseif($report['type']==='expenses'): ?><table class="summary"><tr><td class="yellow"><div class="label">Total pengeluaran dibayar</div><div class="value"><?= $money($data['total']) ?></div></td><td><div class="label">Dokumen</div><div class="value"><?= count($data['rows']) ?></div></td></tr></table><h2>Rekap Kategori</h2><table class="data"><thead><tr><th>Kategori</th><th class="right">Total</th></tr></thead><tbody><?php if($data['byCategory']===[]): ?><tr><td colspan="2">Tidak ada data pada periode ini</td></tr><?php else: ?><?php foreach($data['byCategory'] as $category=>$amount): ?><tr><td><?= esc($category) ?></td><td class="right"><?= $money($amount) ?></td></tr><?php endforeach ?><?php endif ?></tbody></table><h2>Detail Pengeluaran</h2><table class="data"><thead><tr><th>Nomor</th><th>Tanggal</th><th>Kategori</th><th>Deskripsi</th><th>Sumber</th><th class="right">Nominal</th></tr></thead><tbody><?php if($data['rows']===[]): ?><tr><td colspan="6">Tidak ada data pada periode ini</td></tr><?php else: ?><?php foreach($data['rows'] as $row): ?><tr><td><?= esc($row['expense_number']) ?></td><td><?= esc(date('d/m/Y',strtotime($row['posting_date']))) ?></td><td><?= esc($row['category_name']) ?></td><td><?= esc($row['description']) ?></td><td><?= esc($row['payment_source']) ?></td><td class="right"><?= $money((float)$row['amount']) ?></td></tr><?php endforeach ?><?php endif ?></tbody></table>
<?php elseif($report['type']==='shifts'): ?><table class="summary"><tr><td class="yellow"><div class="label">Jumlah shift</div><div class="value"><?= count($data['rows']) ?></div></td><td><div class="label">Total kas seharusnya</div><div class="value"><?= $money($data['expected']) ?></div></td><td><div class="label">Total selisih</div><div class="value"><?= $money($data['difference']) ?></div></td></tr></table><h2>Detail Shift</h2><table class="data"><thead><tr><th>Shift</th><th>Kasir</th><th>Dibuka</th><th>Ditutup</th><th>Status</th><th class="right">Seharusnya</th><th class="right">Fisik</th><th class="right">Selisih</th></tr></thead><tbody><?php if($data['rows']===[]): ?><tr><td colspan="8">Tidak ada data pada periode ini</td></tr><?php else: ?><?php foreach($data['rows'] as $row): ?><tr><td><?= esc($row['shift_number']) ?></td><td><?= esc($row['cashier_name']) ?></td><td><?= esc(date('d/m/Y H:i',strtotime($row['opened_at']))) ?></td><td><?= $row['closed_at']?esc(date('d/m/Y H:i',strtotime($row['closed_at']))):'-' ?></td><td><?= esc($row['status']) ?></td><td class="right"><?= $money((float)($row['expected_cash']??0)) ?></td><td class="right"><?= $money((float)($row['actual_cash']??0)) ?></td><td class="right"><?= $money((float)($row['cash_difference']??0)) ?></td></tr><?php endforeach ?><?php endif ?></tbody></table>
<?php else: ?><table class="summary"><tr><td class="yellow"><div class="label">Laba bersih periode</div><div class="value"><?= $money($data['profit']) ?></div></td><td><div class="label">Total debit</div><div class="value"><?= $money($data['debit']) ?></div></td><td><div class="label">Total kredit</div><div class="value"><?= $money($data['credit']) ?></div></td></tr></table><h2>Neraca Saldo Aktivitas</h2><table class="data"><thead><tr><th>Kode</th><th>Akun</th><th>Kelompok</th><th class="right">Debit</th><th class="right">Kredit</th></tr></thead><tbody><?php $visible=array_filter($data['rows'],static fn(array $r):bool=>(float)$r['debit']!==0.0||(float)$r['credit']!==0.0); ?><?php if($visible===[]): ?><tr><td colspan="5">Tidak ada data pada periode ini</td></tr><?php else: ?><?php foreach($visible as $row): ?><tr><td><?= esc($row['code']) ?></td><td><?= esc($row['name']) ?></td><td><?= esc($row['account_type']) ?></td><td class="right"><?= $money((float)$row['debit']) ?></td><td class="right"><?= $money((float)$row['credit']) ?></td></tr><?php endforeach ?><?php endif ?></tbody></table><?php endif ?>
</body></html>
